modifications.process_replace:
result = state.get('result')
hid = state.get('head_id') or ''
tid = state.get('tail_id') or ''
text = state.get('text') or ''
head = state.get('head') or ''
tail = state.get('tail') or ''

if result == '$' and hid and tid:
    text_lower = text.lower()
    head_lower = head.lower()
    tail_lower = tail.lower()

    # Negation guard: require negation phrase within 50 chars of BOTH head AND tail
    negation_phrases = [
        'did not cause', 'did not induce', 'did not result', 'did not lead',
        'no effect', 'not associated', 'not cause', 'not induce',
        'not result in', 'not lead to', 'failed to', 'unable to',
        'no evidence', 'not significant', 'does not cause', 'does not induce',
        'no evidence of', 'without', 'not associated with', 'no indication of',
        'not related to', 'no sign of', 'not due to'
    ]
    override = False
    for phrase in negation_phrases:
        idx = text_lower.find(phrase)
        if idx == -1:
            continue
        # Find head position
        hidx = text_lower.find(head_lower) if head_lower else -1
        # Find tail position
        tidx = text_lower.find(tail_lower) if tail_lower else -1
        # Require proximity to BOTH head and tail
        head_near = hidx != -1 and abs(idx - hidx) <= 50
        tail_near = tidx != -1 and abs(idx - tidx) <= 50
        if head_near and tail_near:
            override = True
            break

    if not override:
        # Causal override: if explicit causal language near terms, skip associative guard
        causal_patterns = [
            f'{head_lower}-induced {tail_lower}',
            f'{head_lower}-associated {tail_lower}',
        ]
        has_causal = False
        for cp in causal_patterns:
            if cp in text_lower:
                has_causal = True
                break
        if not has_causal:
            causal_verbs = ['cause', 'caused', 'induces', 'induced', 'result in', 'resulted in', 'lead to', 'led to']
            for verb in causal_verbs:
                vidx = text_lower.find(verb)
                if vidx == -1:
                    continue
                for term in [head_lower, tail_lower]:
                    if not term:
                        continue
                    tidx = text_lower.find(term)
                    if tidx == -1:
                        continue
                    if abs(vidx - tidx) <= 100:
                        has_causal = True
                        break
                if has_causal:
                    break

        if not has_causal:
            # Relaxed associative guard: only override if phrase within 15 chars
            associative_phrases = [
                'associated with', 'linked to', 'correlated with', 'related to',
                'risk factor', 'risk of', 'presumably', 'suggest', 'may', 'could',
                'possible', 'might', 'co-occurrence'
            ]
            for phrase in associative_phrases:
                idx = text_lower.find(phrase)
                if idx == -1:
                    continue
                for term in [head_lower, tail_lower]:
                    if not term:
                        continue
                    tidx = text_lower.find(term)
                    if tidx == -1:
                        continue
                    if abs(idx - tidx) <= 15:
                        override = True
                        break
                if override:
                    break

    if override:
        __result__ = []
    else:
        __result__ = [f"{hid} | {tid}"]
else:
    __result__ = []
